        calls.append(kwargs['optimize'])
        return {'ok': True, 'artifact': artifact, 'crate_type': 'bin',
                'rustc_crate_type': 'bin'}

    def run_contract(args, *positional, **kwargs):
        if args == [compiler, '--version']:
